import java.util.HashMap;
import java.util.Map;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import net.runelite.client.util.ImageUtil;

/**
 * Ranks the task's locations for this account, keeps the chosen destination,
 * pins it on the world map and feeds the on-screen direction hint. It shows
 * the way; it never walks it.
 */
@Slf4j
@Singleton
public class Advisor
{
	private final Client client;
	private final SlayerSuiteConfig config;
	private final TaskTracker tracker;
	private final AccountState account;
	private final TravelData travel;
	private final ReadinessChecker readiness;
	private final WorldMapPointManager mapPoints;
	private final LocationScorer scorer;
	private final EventBus eventBus;

	private volatile List<ScoredLocation> ranked = Collections.emptyList();
	@Getter
	private volatile LocationRecord destination;
	@Getter
	private volatile boolean arrived;
	private WorldMapPoint pin;
	private BufferedImage pinImage;
	private long lastBankRefresh;
	private int tick;
	@Setter
	private Runnable listener;

	// Values the side panel reads from the Swing thread; refreshed on the client thread each tick.
	private volatile int cachedDistance = -1;
	private volatile String cachedDirection = "";
	private volatile List<TravelOption> cachedTravel = Collections.emptyList();
	private volatile LocationRecord cachedTravelFor;
	/** The one thing to do next to get to the pin, in words; refreshed each tick on the client thread. */
	@Getter
	private volatile String nextStep = "";

	@Inject
	public Advisor(Client client, SlayerSuiteConfig config, TaskTracker tracker, AccountState account, TravelData travel, ReadinessChecker readiness, WorldMapPointManager mapPoints, EventBus eventBus)
	{
		this.eventBus = eventBus;
		this.client = client;
		this.config = config;
		this.tracker = tracker;
		this.account = account;
		this.travel = travel;
		this.readiness = readiness;
		this.mapPoints = mapPoints;
		this.scorer = new LocationScorer(travel);
	}

	public void reset()
	{
		ranked = Collections.emptyList();
		clearDestination();
	}

	public List<ScoredLocation> ranked()
	{
		return ranked;
	}

	/** Krystilia's tasks live in the Wilderness by definition: never penalise or hide them for it. */
	public boolean wildernessTask()
	{
		com.slayersuite.task.GameTaskTable.GameTask gt = tracker.getGameTask();
		return gt != null && gt.getMasterId() == 7;
	}

	/** Supplies your per-spot rates for a task key; set by the plugin at startup. */
	private volatile java.util.function.Function<String, java.util.Map<String, double[]>> ownRatesSource;

	public void setOwnRatesSource(java.util.function.Function<String, java.util.Map<String, double[]>> source)
	{
		ownRatesSource = source;
	}

	private LocationScorer.Options options()
	{
		LocationScorer.Options o = new LocationScorer.Options();
		o.avoidWilderness = config.avoidWilderness() && !wildernessTask();
		TaskRecord rec = tracker.getRecord();
		java.util.function.Function<String, java.util.Map<String, double[]>> src = ownRatesSource;
		if (rec != null && src != null)
		{
			o.ownRates = src.apply(rec.getKey());
		}
		o.preferCannon = config.preferCannon();
		o.preferMulti = true;
		return o;
	}

	/** The ranked list after the panel's filters. */
	public List<ScoredLocation> filtered()
	{
		List<ScoredLocation> out = new ArrayList<>();
		for (ScoredLocation s : ranked)
		{
			LocationRecord l = s.getLocation();
			if (config.filterCannon() && !Boolean.TRUE.equals(l.getCannon()))
			{
				continue;
			}
			if (config.filterMulti() && !Boolean.TRUE.equals(l.getMulticombat()))
			{
				continue;
			}
			if (config.filterSafespot() && !Boolean.TRUE.equals(l.getSafespot()))
			{
				continue;
			}
			if (config.filterNoWilderness() && s.isWilderness() && !wildernessTask())
			{
				continue;
			}
			if (config.hideLocked() && s.isLocked())
			{
				continue;
			}
			out.add(s);
		}
		return out;
	}

	public ScoredLocation best()
	{
		for (ScoredLocation s : filtered())
		{
			if (!s.isLocked())
			{
				return s;
			}
		}
		for (ScoredLocation s : ranked)
		{
			if (!s.isLocked())
			{
				return s;
			}
		}
		return null;
	}

	/** Rank any task's locations for this account (used by the task choice screen). */
	public List<ScoredLocation> rankFor(TaskRecord rec)
	{
		return rec == null ? Collections.emptyList() : scorer.rank(rec, account, options());
	}

	public void refresh()
	{
		TaskRecord rec = tracker.getRecord();
		List<ScoredLocation> list = rec == null ? Collections.emptyList() : scorer.rank(rec, account, options());
		// Konar assigns a place with the monster: only spots in that area count, when the dataset knows any of them.
		String area = tracker.getTaskLocation();
		if (area != null && !area.isEmpty() && !list.isEmpty())
		{
			List<ScoredLocation> inArea = new ArrayList<>();
			for (ScoredLocation s : list)
			{
				if (samePlace(area, s.getLocation().getName()))
				{
					inArea.add(s);
				}
			}
			if (!inArea.isEmpty())
			{
				list = inArea;
			}
		}
		ranked = Collections.unmodifiableList(list);
		notifyListener();
	}

	/** Loose place-name match: equal, one inside the other, or the same first two words ("Fremennik Slayer Dungeon" and "... Cave"). */
	public static boolean samePlace(String a, String b)
	{
		String na = a.toLowerCase().replaceAll("[^a-z ]", " ").replaceAll("\\s+", " ").trim();
		String nb = b.toLowerCase().replaceAll("[^a-z ]", " ").replaceAll("\\s+", " ").trim();
		if (na.isEmpty() || nb.isEmpty())
		{
			return false;
		}
		if (na.equals(nb) || (na.length() > 6 && (nb.contains(na) || na.contains(nb))))
		{
			return true;
		}
		String[] wa = na.split(" ");
		String[] wb = nb.split(" ");
		return wa.length >= 2 && wb.length >= 2 && wa[0].equals(wb[0]) && wa[1].equals(wb[1]);
	}

	private void notifyListener()
	{
		Runnable l = listener;
		if (l != null)
		{
			l.run();
		}
	}

	// ---------------------------------------------------------------- destination

	/** Within this many tiles of a spawn pin counts as having arrived. */
	private static final int ARRIVE_TILES = 10;

	/** Distance in tiles from the player to the nearest spawn pin of the location (or its centre), or -1. Client thread. */
	public int tilesToNearestSpawn(LocationRecord loc)
	{
		Player me = client.getLocalPlayer();
		if (loc == null || me == null)
		{
			return -1;
		}
		WorldPoint wp = me.getWorldLocation();
		int plane = loc.getPlane() == null ? 0 : loc.getPlane();
		if (wp.getPlane() != plane)
		{
			return -1;
		}
		int best = -1;
		if (loc.getPins() != null)
		{
			for (List<Integer> pin : loc.getPins())
			{
				if (pin == null || pin.size() < 2)
				{
					continue;
				}
				int d = (int) Math.round(Math.hypot(pin.get(0) - wp.getX(), pin.get(1) - wp.getY()));
				if (best < 0 || d < best)
				{
					best = d;
				}
			}
		}
		if (best < 0 && loc.hasCoordinates())
		{
			best = (int) Math.round(Math.hypot(loc.getX() - wp.getX(), loc.getY() - wp.getY()));
		}
		return best;
	}

	private boolean nearSpawn(LocationRecord loc)
	{
		int d = tilesToNearestSpawn(loc);
		return d >= 0 && d <= ARRIVE_TILES;
	}

	public void setDestination(LocationRecord loc)
	{
		destination = loc;
		arrived = loc != null && nearSpawn(loc);
		updatePin();
		handToShortestPath();
		notifyListener();
	}

	public void clearDestination()
	{
		destination = null;
		arrived = false;
		updatePin();
		handToShortestPath();
		notifyListener();
	}

	/**
	 * The Shortest Path plugin (Hub) owns a full world map with doors, shortcuts and transports.
	 * When it is installed, it draws the whole route for the pin; without it nothing happens.
	 */
	private void handToShortestPath()
	{
		if (!config.handToShortestPath())
		{
			return;
		}
		try
		{
			WorldPoint wp = arrived ? null : destinationPoint();
			if (wp == null)
			{
				eventBus.post(new PluginMessage("shortestpath", "clear"));
			}
			else
			{
				Map<String, Object> data = new HashMap<>();
				data.put("target", wp);
				eventBus.post(new PluginMessage("shortestpath", "path", data));
			}
		}
		catch (RuntimeException e)
		{
			log.debug("shortest path hand-off failed", e);
		}
	}

	/** Words for the next move: use a teleport you own, or walk. Client thread. */
	private String computeNextStep(LocationRecord dest)
	{
		if (dest == null)
		{
			return "";
		}
		if (arrived)
		{
			return "You are there";
		}
		Player me0 = client.getLocalPlayer();
		if (me0 != null && dest.getPlane() != null && me0.getWorldLocation().getPlane() != dest.getPlane() && inRegionOf(dest))
		{
			// right place, wrong floor: the floor path and the tile distance cannot say this
			int up = dest.getPlane() - me0.getWorldLocation().getPlane();
			return (up > 0 ? "Go up " : "Go down ") + Math.abs(up) + (Math.abs(up) == 1 ? " floor" : " floors") + " to " + floorName(dest.getPlane()) + "; the spawns are there";
		}
		int dist = distanceFromPlayer();
		String dir = directionFromPlayer();
		WorldPoint dp = destinationPoint();
		if (me0 != null && dp != null && dist >= 0 && dist <= 60 && underground(dp.getY()) != underground(me0.getWorldLocation().getY()))
		{
			return underground(dp.getY()) ? "Go down into " + dest.getName() + "; the entrance is within " + Math.max(dist, 5) + " tiles " + dir
				: "Come up to the surface; " + dest.getName() + " is " + Math.max(dist, 5) + " tiles " + dir + " from here";
		}
		int toSpawn = tilesToNearestSpawn(dest);
		if (toSpawn >= 0 && toSpawn < dist)
		{
			dist = toSpawn;
		}
		if (dist < 0)
		{
			return "";
		}
		Player me = client.getLocalPlayer();
		WorldPoint here = me == null ? null : me.getWorldLocation();
		TravelOption best = null;
		for (TravelOption o : cachedTravel)
		{
			if (o.isUsable())
			{
				best = o;
				break;
			}
		}
		// Already close to where the best teleport lands, or close to the spot itself: walk.
		boolean nearLanding = best != null && best.getLanding() != null && here != null
			&& Math.hypot(best.getLanding()[0] - here.getX(), best.getLanding()[1] - here.getY()) < 40;
		if (dist <= config.floorPathMaxDistance() || nearLanding)
		{
			return "Walk " + TripMath.formatK(dist) + " tiles " + dir + (dist <= config.floorPathMaxDistance() ? " (follow the tiles)" : "");
		}
		if (best != null)
		{
			String how = best.getLabel().replace("House: ", "house ");
			String where = best.getStatus().equals("in bank") ? " (it is in your bank)" : best.getStatus().startsWith("needs") ? " (" + best.getStatus() + ")" : "";
			return "Use " + how + where + ", then " + (best.getHops() <= 1 ? "you are there" : best.getHops() == 2 ? "a short run" : "a long run");
		}
		return "Head " + dir + ", " + TripMath.formatK(dist) + " tiles; no teleport you own";
	}

	/** True when one of the loaded map squares belongs to the location. */
	private boolean inRegionOf(LocationRecord loc)
	{
		net.runelite.api.WorldView wv = client.getTopLevelWorldView();
		int[] regions = wv == null ? null : wv.getMapRegions();
		if (regions == null)
		{
			return false;
		}
		for (int r : regions)
		{
			if (loc.coversRegion(r))
			{
				return true;
			}
		}
		return false;
	}

	private static String floorName(int plane)
	{
		switch (plane)
		{
			case 0: return "the ground floor";
			case 1: return "the first floor";
			case 2: return "the second floor";
			default: return "floor " + plane;
		}
	}

	private void updatePin()
	{
		if (pin != null)
		{
			mapPoints.remove(pin);
			pin = null;
		}
		LocationRecord loc = destination;
		if (loc == null || !loc.hasCoordinates() || arrived)
		{
			return;
		}
		if (pinImage == null)
		{
			try
			{
				BufferedImage raw = ImageUtil.loadImageResource(Advisor.class, "/com/slayersuite/icon.png");
				pinImage = raw == null ? null : ImageUtil.resizeImage(raw, 20, 20);
			}
			catch (RuntimeException e)
			{
				pinImage = null;
			}
		}
		WorldMapPoint.WorldMapPointBuilder<?, ?> b = WorldMapPoint.builder()
			.worldPoint(destinationPoint())
			.name(loc.getName())
			.tooltip("Slayer Suite: " + loc.getName())
			.snapToEdge(true)
			.jumpOnClick(true);
		if (pinImage != null)
		{
			b.image(pinImage);
		}
		pin = b.build();
		mapPoints.add(pin);
	}

	public WorldPoint destinationPoint()
	{
		LocationRecord loc = destination;
		if (loc == null || !loc.hasCoordinates())
		{
			return null;
		}
		int plane = loc.getPlane() == null ? 0 : loc.getPlane();
		return new WorldPoint(loc.getX(), loc.getY(), plane);
	}

	public static boolean sameLocation(LocationRecord a, LocationRecord b)
	{
		return a != null && b != null && a.getName() != null && a.getName().equals(b.getName());
	}

	/** Last distance computed on the client thread; safe to read from Swing. */
	public int cachedDistance()
	{
		return cachedDistance;
	}

	public String cachedDirection()
	{
		return cachedDirection;
	}

	/** Travel options for the pinned (or best) spot, computed on the client thread; safe to read from Swing. */
	public List<TravelOption> cachedTravelOptions(LocationRecord loc)
	{
		LocationRecord f = cachedTravelFor;
		return f != null && loc != null && sameLocation(f, loc) ? cachedTravel : Collections.emptyList();
	}

	/** Distance in tiles from the player to the destination, ignoring plane; -1 when unknown. Client thread only. */
	public int distanceFromPlayer()
	{
		WorldPoint dest = destinationPoint();
		Player me = client.getLocalPlayer();
		if (dest == null || me == null)
		{
			return -1;
		}
		WorldPoint wp = me.getWorldLocation();
		return (int) Math.round(Math.hypot(dest.getX() - wp.getX(), surfaceY(dest.getY()) - surfaceY(wp.getY())));
	}

	/** Dungeons are stored 6400 tiles north of the ground above them; fold that away for distances and headings. */
	static int surfaceY(int y)
	{
		return y >= 6400 ? y - 6400 : y;
	}

	private static boolean underground(int y)
	{
		return y >= 6400;
	}

	/** Eight-point compass direction from the player to the destination. */
	public String directionFromPlayer()
	{
		WorldPoint dest = destinationPoint();
		Player me = client.getLocalPlayer();
		if (dest == null || me == null)
		{
			return "";
		}
		WorldPoint wp = me.getWorldLocation();
		return compass(dest.getX() - wp.getX(), surfaceY(dest.getY()) - surfaceY(wp.getY()));
	}

	static String compass(int dx, int dy)
	{
		if (dx == 0 && dy == 0)
		{
			return "here";
		}
		double ang = Math.toDegrees(Math.atan2(dx, dy)); // 0 = north, clockwise
		if (ang < 0)
		{
			ang += 360;
		}
		String[] names = {"N", "NE", "E", "SE", "S", "SW", "W", "NW"};
		return names[(int) Math.round(ang / 45.0) % 8];
	}

	/** The ranked entry for the destination, if any. */
	public ScoredLocation destinationScore()
	{
		LocationRecord d = destination;
		if (d == null)
		{
			return null;
		}
		for (ScoredLocation s : ranked)
		{
			if (sameLocation(s.getLocation(), d))
			{
				return s;
			}
		}
		return null;
	}

	/** Every known way to a location, with whether the account can use it right now. */
	public List<TravelOption> travelOptions(LocationRecord loc)
	{
		List<TravelOption> out = new ArrayList<>();
		TravelData.Entry e = loc == null ? null : travel.find(loc.getName());
		if (e == null)
		{
			return out;
		}
		for (TravelData.Teleport t : e.getTeleports())
		{
			boolean usable;
			String status;
			int hops = t.getHops();
			if (t.getPoh() != null)
			{
				boolean jewellery = t.getItem() != null && t.getPoh().equalsIgnoreCase("Jewellery Box");
				usable = jewellery ? account.jewelleryBoxCovers(t.getItem()) : account.hasHouseFacility(t.getPoh());
				if (!account.houseScanned())
				{
					status = "house not scanned yet";
				}
				else if (!usable)
				{
					status = "not in your house";
				}
				else if (!account.canTeleportHome())
				{
					hops += 1;
					status = "in your house (no quick way home)";
				}
				else
				{
					status = "in your house";
				}
			}
			else if (t.getItem() != null)
			{
				String n = com.slayersuite.data.ItemNames.normalize(t.getItem());
				if (readiness.heldNames().contains(n) || startsWithAny(readiness.heldNames(), n))
				{
					usable = true;
					status = "carried";
				}
				else if (readiness.bankNames().contains(n) || startsWithAny(readiness.bankNames(), n))
				{
					usable = true;
					status = "in bank";
				}
				else if (readiness.owns(t.getItem()))
				{
					usable = true;
					status = "seen in your bank before";
				}
				else
				{
					usable = false;
					status = readiness.anythingRemembered() ? "not owned" : "not seen yet (open your bank)";
				}
			}
			else if (t.getFairy() != null)
			{
				usable = account.fairyRingsUsable();
				status = usable ? "fairy rings" : "fairy rings locked (Fairytale II + staff)";
			}
			else if (t.getSpell() != null)
			{
				int magic = account.skillLevel("MAGIC");
				if (t.getQuest() != null && !account.questFinished(t.getQuest()))
				{
					usable = false;
					status = "needs " + LocationScorer.pretty(t.getQuest());
				}
				else if (t.getLevel() > 0 && magic >= 0 && magic < t.getLevel())
				{
					usable = false;
					status = "needs " + t.getLevel() + " Magic (you have " + magic + ")";
				}
				else
				{
					int book = LocationScorer.bookIndex(t.getBook());
					int have = account.spellbook();
					usable = true;
					if (book >= 0 && have >= 0 && have != book)
					{
						hops += 1;
						status = "needs the " + t.getBook() + " spellbook";
					}
					else
					{
						status = "spell";
					}
				}
			}
			else
			{
				continue;
			}
			out.add(new TravelOption(t.label(), hops, usable, status, TravelData.landing(t)));
		}
		out.sort((a, b) ->
		{
			if (a.isUsable() != b.isUsable())
			{
				return a.isUsable() ? -1 : 1;
			}
			return Integer.compare(a.getHops(), b.getHops());
		});
		return out;
	}

	private static boolean startsWithAny(java.util.Set<String> pool, String want)
	{
		for (String have : pool)
		{
			if (have.startsWith(want + " ") || have.startsWith(want + "("))
			{
				return !have.contains("(inert)") && !have.contains("(uncharged)") && !have.contains("(empty)");
			}
		}
		return false;
	}

	// ---------------------------------------------------------------- events

	@Subscribe
	public void onTaskChanged(TaskChanged e)
	{
		if (e.getNewName() == null)
		{
			ranked = Collections.emptyList();
			clearDestination();
			return;
		}
		refresh();
		ScoredLocation best = best();
		if (config.autoDestination())
		{
			setDestination(best == null ? null : best.getLocation());
		}
		else
		{
			clearDestination();
		}
		if (config.advisorChat() && best != null && client.getGameState() == GameState.LOGGED_IN)
		{
			String hint = "";
			if (!readiness.anythingRemembered() && !account.houseScanned())
			{
				hint = " Open your bank and stand in your house once so I know your teleports.";
			}
			else if (!readiness.anythingRemembered())
			{
				hint = " Open your bank once so I know your jewellery and tablets.";
			}
			else if (!account.houseScanned())
			{
				hint = " Stand in your house once so I know its portals.";
			}
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "<col=00a0ff>Slayer Suite:</col> Best spot for you: " + best.getLocation().getName()
				+ (best.getReasons().isEmpty() ? "" : " (" + String.join(", ", best.getReasons()) + ")") + "." + hint, null);
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged e)
	{
		if (e.getContainerId() == InventoryID.BANK && tracker.hasTask())
		{
			long now = System.currentTimeMillis();
			if (now - lastBankRefresh > 5_000L)
			{
				lastBankRefresh = now;
				refresh();
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		if (!SlayerSuiteConfig.GROUP.equals(e.getGroup()) || e.getKey() == null)
		{
			return;
		}
		String k = e.getKey();
		if (k.startsWith("filter") || k.equals("hideLocked") || k.equals("avoidWilderness") || k.equals("preferCannon"))
		{
			refresh();
		}
	}

	@Subscribe
	public void onGameTick(GameTick t)
	{
		LocationRecord focus = destination;
		if (focus == null)
		{
			ScoredLocation b = best();
			focus = b == null ? null : b.getLocation();
		}
		if (focus != null)
		{
			if (destination != null)
			{
				cachedDistance = distanceFromPlayer();
				cachedDirection = directionFromPlayer();
			}
			else
			{
				cachedDistance = -1;
				cachedDirection = "";
			}
			if (cachedTravelFor == null || !sameLocation(cachedTravelFor, focus) || tick % 10 == 0)
			{
				cachedTravel = travelOptions(focus);
				cachedTravelFor = focus;
			}
			nextStep = destination != null ? computeNextStep(destination) : "";
		}
		else
		{
			cachedDistance = -1;
			cachedDirection = "";
			cachedTravel = Collections.emptyList();
			cachedTravelFor = null;
			nextStep = "";
		}
		if (++tick % 5 != 0)
		{
			return;
		}
		if (ranked.isEmpty() && tracker.getRecord() != null)
		{
			refresh();
		}
		LocationRecord here = tracker.getCurrentLocation();
		if (here != null && nearSpawn(here) && (destination == null || !sameLocation(here, destination)))
		{
			// you reached one of the task's spots, pinned or not: that is the destination now
			destination = here;
			arrived = true;
			updatePin();
			handToShortestPath();
			notifyListener();
		}
		LocationRecord d = destination;
		if (d != null)
		{
			boolean near = nearSpawn(d);
			if (near && !arrived)
			{
				arrived = true;
				updatePin();
				handToShortestPath();
				notifyListener();
			}
			else if (!near && arrived && tilesToNearestSpawn(d) > ARRIVE_TILES * 3)
			{
				// wandered well away from the spawns again: guide back
				arrived = false;
				updatePin();
				handToShortestPath();
				notifyListener();
			}
		}
	}
}

package com.slayersuite.advisor;

import com.slayersuite.SlayerSuiteConfig;
import com.slayersuite.trip.TripMath;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** An arrow on the minimap edge pointing at the chosen spot, with the distance. Display only. */
public class GpsOverlay extends Overlay
{
	private static final Color ARROW = new Color(80, 220, 255);
	private static final Color OUTLINE = new Color(0, 0, 0, 180);

	private final Client client;
	private final Advisor advisor;
	private final SlayerSuiteConfig config;
	private final com.slayersuite.task.SlayerMode mode;

	@Inject
	public GpsOverlay(Client client, Advisor advisor, SlayerSuiteConfig config, com.slayersuite.task.SlayerMode mode)
	{
		this.mode = mode;
		this.client = client;
		this.advisor = advisor;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.gpsArrow() || advisor.getDestination() == null || advisor.isArrived() || !mode.active())
		{
			return null;
		}
		WorldPoint dest = advisor.destinationPoint();
		Player me = client.getLocalPlayer();
		if (dest == null || me == null)
		{
			return null;
		}
		WorldPoint wp = me.getWorldLocation();
		int dx = dest.getX() - wp.getX();
		int dy = dest.getY() - wp.getY();
		double len = Math.hypot(dx, dy);
		if (len < 6)
		{
			return null;
		}
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return null;
		}
		// a point ten tiles toward the destination is always in the loaded scene
		int px = wp.getX() + (int) Math.round(dx / len * 10);
		int py = wp.getY() + (int) Math.round(dy / len * 10);
		LocalPoint toward = LocalPoint.fromWorld(wv, px, py);
		LocalPoint here = me.getLocalLocation();
		if (toward == null || here == null)
		{
			return null;
		}
		Point tip = Perspective.localToMinimap(client, toward);
		Point centre = Perspective.localToMinimap(client, here);
		if (tip == null || centre == null)
		{
			return null;
		}
		double ang = Math.atan2(tip.getY() - centre.getY(), tip.getX() - centre.getX());
		int size = 9;
		Polygon tri = new Polygon();
		tri.addPoint((int) Math.round(tip.getX() + Math.cos(ang) * size), (int) Math.round(tip.getY() + Math.sin(ang) * size));
		tri.addPoint((int) Math.round(tip.getX() + Math.cos(ang + 2.5) * size), (int) Math.round(tip.getY() + Math.sin(ang + 2.5) * size));
		tri.addPoint((int) Math.round(tip.getX() + Math.cos(ang - 2.5) * size), (int) Math.round(tip.getY() + Math.sin(ang - 2.5) * size));
		Object aa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(ARROW);
		g.fillPolygon(tri);
		g.setColor(OUTLINE);
		g.setStroke(new BasicStroke(1.5f));
		g.drawPolygon(tri);
		g.setFont(FontManager.getRunescapeSmallFont());
		String label = TripMath.formatK(Math.round(len));
		int tx = (int) Math.round(tip.getX() + Math.cos(ang) * (size + 10)) - g.getFontMetrics().stringWidth(label) / 2;
		int ty = (int) Math.round(tip.getY() + Math.sin(ang) * (size + 10)) + 4;
		g.setColor(Color.BLACK);
		g.drawString(label, tx + 1, ty + 1);
		g.setColor(ARROW);
		g.drawString(label, tx, ty);
		if (aa != null)
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa);
		}
		return null;
	}
}

package com.slayersuite.advisor;

import com.google.gson.Gson;
import com.slayersuite.SlayerSuiteConfig;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.TreeSet;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ObjectComposition;
import net.runelite.api.WorldView;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;

/**
 * Remembers what teleport furniture your house has. The client only shows the
 * house while you stand in it, so every visit updates a list saved on the
 * RuneScape profile: portals, portal nexus, jewellery box tier, mounted glory,
 * talisman, pendant and cape, fairy ring, spirit tree, spellbook altars.
 */
@Slf4j
@Singleton
public class HouseScanner
{
	static final String KEY = "house";

	/** Object names (lower case) that only exist inside a player-owned house. */
	private static final Set<String> FACILITIES = new HashSet<>(Arrays.asList(
		"portal nexus", "fairy ring", "spirit tree", "spiritual fairy tree",
		"basic jewellery box", "fancy jewellery box", "ornate jewellery box",
		"amulet of glory", "xeric's talisman", "digsite pendant", "mythical cape",
		"occult altar", "altar of the occult", "ancient altar", "lunar altar", "dark altar",
		"obelisk", "pool of restoration", "pool of revitalisation", "pool of rejuvenation", "fancy pool of rejuvenation", "ornate pool of rejuvenation"));

	public static class House
	{
		public Set<String> facilities = new TreeSet<>();
		public boolean nexus;
		public boolean nexusXeric;
		public boolean nexusDigsite;
		public long updated;
	}

	private final Client client;
	private final ConfigManager configManager;
	private final Gson gson;

	@Getter
	private House house = new House();
	private boolean loaded;
	private boolean dirty;
	private int tick;

	@Inject
	public HouseScanner(Client client, ConfigManager configManager, Gson gson)
	{
		this.client = client;
		this.configManager = configManager;
		this.gson = gson;
	}

	public void reset()
	{
		loaded = false;
		dirty = false;
	}

	// ---------------------------------------------------------------- persistence

	private void load()
	{
		house = new House();
		try
		{
			String json = configManager.getRSProfileConfiguration(SlayerSuiteConfig.GROUP, KEY);
			if (json != null && !json.isEmpty())
			{
				House h = gson.fromJson(json, House.class);
				if (h != null)
				{
					if (h.facilities == null)
					{
						h.facilities = new TreeSet<>();
					}
					house = h;
				}
			}
		}
		catch (RuntimeException e)
		{
			log.debug("house load failed", e);
		}
		loaded = true;
	}

	private void save()
	{
		if (configManager.getRSProfileKey() == null)
		{
			return;
		}
		try
		{
			house.updated = System.currentTimeMillis();
			configManager.setRSProfileConfiguration(SlayerSuiteConfig.GROUP, KEY, gson.toJson(house));
			dirty = false;
		}
		catch (RuntimeException e)
		{
			log.debug("house save failed", e);
		}
	}

	// ---------------------------------------------------------------- queries

	public boolean scanned()
	{
		return house.updated > 0;
	}

	public boolean has(String facility)
	{
		if (facility == null)
		{
			return false;
		}
		String f = facility.toLowerCase(Locale.ROOT);
		if (f.equals("portal nexus"))
		{
			return house.nexus;
		}
		if (f.equals("fairy ring"))
		{
			return house.facilities.contains("fairy ring") || house.facilities.contains("spiritual fairy tree");
		}
		if (f.equals("spirit tree"))
		{
			return house.facilities.contains("spirit tree") || house.facilities.contains("spiritual fairy tree");
		}
		if (f.equals("xeric's talisman"))
		{
			return house.facilities.contains(f) || house.nexusXeric;
		}
		if (f.equals("digsite pendant"))
		{
			return house.facilities.contains(f) || house.nexusDigsite;
		}
		return house.facilities.contains(f);
	}

	/** Jewellery box tiers: basic = dueling and games; fancy adds skills and combat; ornate adds glory and wealth. */
	public boolean jewelleryBoxCovers(String itemName)
	{
		if (itemName == null)
		{
			return false;
		}
		String n = itemName.toLowerCase(Locale.ROOT);
		boolean basic = house.facilities.contains("basic jewellery box") || house.facilities.contains("fancy jewellery box") || house.facilities.contains("ornate jewellery box");
		boolean fancy = house.facilities.contains("fancy jewellery box") || house.facilities.contains("ornate jewellery box");
		boolean ornate = house.facilities.contains("ornate jewellery box");
		if (n.startsWith("ring of dueling") || n.startsWith("games necklace"))
		{
			return basic;
		}
		if (n.startsWith("skills necklace") || n.startsWith("combat bracelet"))
		{
			return fancy;
		}
		if (n.startsWith("amulet of glory") || n.startsWith("ring of wealth"))
		{
			return ornate;
		}
		return false;
	}

	public boolean hasSpellbookAltar()
	{
		return house.facilities.contains("occult altar") || house.facilities.contains("altar of the occult")
			|| house.facilities.contains("ancient altar") || house.facilities.contains("lunar altar") || house.facilities.contains("dark altar");
	}

	public Set<String> facilities()
	{
		return Collections.unmodifiableSet(house.facilities);
	}

	public String summary()
	{
		if (!scanned())
		{
			return "Not scanned yet: stand in your house once and I will remember its teleports.";
		}
		Set<String> all = new TreeSet<>(house.facilities);
		if (house.nexus)
		{
			all.add("portal nexus" + (house.nexusXeric ? " (xeric)" : "") + (house.nexusDigsite ? " (digsite)" : ""));
		}
		return all.isEmpty() ? "House scanned: no teleport furniture seen." : String.join(", ", all);
	}

	// ---------------------------------------------------------------- events

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOGGED_IN && !loaded)
		{
			load();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged e)
	{
		load();
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned e)
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null || !wv.isInstance() || e.getGameObject() == null)
		{
			return;
		}
		if (!loaded)
		{
			load();
		}
		ObjectComposition def;
		try
		{
			def = client.getObjectDefinition(e.getGameObject().getId());
		}
		catch (RuntimeException ex)
		{
			return;
		}
		if (def == null || def.getName() == null)
		{
			return;
		}
		String name = def.getName().toLowerCase(Locale.ROOT).trim();
		if (name.isEmpty() || name.equals("null"))
		{
			return;
		}
		boolean portal = name.endsWith(" portal") && !name.equals("exit portal");
		if (portal || FACILITIES.contains(name))
		{
			if (name.equals("portal nexus"))
			{
				if (!house.nexus)
				{
					house.nexus = true;
					dirty = true;
				}
			}
			else if (house.facilities.add(name))
			{
				dirty = true;
				log.debug("house: found {}", name);
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick t)
	{
		if (!loaded)
		{
			return;
		}
		if (house.nexus)
		{
			WorldView wv = client.getTopLevelWorldView();
			if (wv != null && wv.isInstance())
			{
				boolean xeric = client.getVarbitValue(VarbitID.POH_NEXUS_XERIC) == 1;
				boolean digsite = client.getVarbitValue(VarbitID.POH_NEXUS_DIGSITE) == 1;
				if (xeric != house.nexusXeric || digsite != house.nexusDigsite)
				{
					house.nexusXeric = xeric;
					house.nexusDigsite = digsite;
					dirty = true;
				}
			}
		}
		if (dirty && ++tick % 10 == 0)
		{
			save();
		}
	}
}

package com.slayersuite.advisor;

import com.slayersuite.data.LocationRecord;
import com.slayersuite.data.TaskRecord;
import java.util.ArrayList;
import java.util.List;

/**
 * Ranks a task's locations for one account. Pure: everything it reads comes
 * through AccountView and the data files, so it can be unit-tested.
 */
public class LocationScorer
{
	public static class Options
	{
		public boolean avoidWilderness = true;
		public boolean preferCannon = true;
		public boolean preferMulti = true;
		/** Spot name -> {kills/h, gp/h, xp/h} from your own history on this task. */
		public java.util.Map<String, double[]> ownRates = java.util.Collections.emptyMap();
	}

	private final TravelData travel;

	public LocationScorer(TravelData travel)
	{
		this.travel = travel;
	}

	public List<ScoredLocation> rank(TaskRecord rec, AccountView account, Options opt)
	{
		List<ScoredLocation> out = new ArrayList<>();
		if (rec == null)
		{
			return out;
		}
		boolean immune = rec.cannonImmune();
		for (LocationRecord loc : rec.getLocations())
		{
			if (Boolean.TRUE.equals(loc.getBoss()))
			{
				continue;
			}
			out.add(score(loc, account, opt, immune));
		}
		out.sort((a, b) -> Integer.compare(b.getScore(), a.getScore()));
		return out;
	}

	public ScoredLocation score(LocationRecord loc, AccountView account, Options opt)
	{
		return score(loc, account, opt, false);
	}

	public ScoredLocation score(LocationRecord loc, AccountView account, Options opt, boolean monstersCannonImmune)
	{
		List<String> reasons = new ArrayList<>();
		int score = 0;
		boolean locked = false;
		TravelData.Entry entry = travel.find(loc.getName());
		boolean wild = isWilderness(loc) || (entry != null && entry.isWilderness());

		if (entry != null)
		{
			for (TravelData.Requirement r : entry.getRequires())
			{
				if (r.getQuest() != null)
				{
					boolean ok = r.isStarted() ? account.questStarted(r.getQuest()) : account.questFinished(r.getQuest());
					if (!ok)
					{
						locked = true;
						reasons.add("needs " + pretty(r.getQuest()) + (r.isStarted() ? " started" : ""));
					}
				}
				if (r.getDiary() != null && !account.diaryComplete(r.getDiary()))
				{
					locked = true;
					reasons.add("needs " + pretty(r.getDiary()) + " diary");
				}
				if (r.getSkill() != null && r.getLevel() > 0)
				{
					int have = account.skillLevel(r.getSkill());
					if (have >= 0 && have < r.getLevel())
					{
						locked = true;
						reasons.add("needs " + r.getLevel() + " " + pretty(r.getSkill()) + " (you have " + have + ")");
					}
				}
			}
		}

		if (Boolean.TRUE.equals(loc.getCannon()))
		{
			if (monstersCannonImmune)
			{
				reasons.add("cannon allowed but the monsters are immune");
			}
			else if (opt.preferCannon && account.ownsCannon())
			{
				if (account.questFinished("DWARF_CANNON"))
				{
					score += 30;
					reasons.add("cannon");
				}
				else
				{
					score += 5;
					reasons.add("cannon (finish Dwarf Cannon first)");
				}
			}
			else
			{
				score += 5;
			}
		}
		if (Boolean.TRUE.equals(loc.getMulticombat()))
		{
			// multi only pays with monsters to share it: a one-spawn multi area is no better than single
			boolean worthIt = loc.getSpawnCount() == 0 || loc.getSpawnCount() >= 3;
			score += worthIt ? (opt.preferMulti ? 20 : 5) : 2;
			reasons.add("multi");
		}
		if (Boolean.TRUE.equals(loc.getSafespot()))
		{
			score += 8;
			reasons.add("safespot");
		}
		score += Math.min(loc.getSpawnCount(), 15);
		String own = null;
		double[] mine = opt.ownRates.get(loc.getName());
		if (mine != null)
		{
			own = Math.round(mine[0]) + " kills/h, " + com.slayersuite.trip.TripMath.formatK(Math.round(mine[1])) + " gp/h for you here";
			// the spot where you have done best, by xp/h then gp/h, gets the edge once you have played two or more
			boolean best = opt.ownRates.size() >= 2;
			for (double[] other : opt.ownRates.values())
			{
				if (other != mine && (other[2] > mine[2] || (other[2] == mine[2] && other[1] > mine[1])))
				{
					best = false;
				}
			}
			if (best)
			{
				score += 15;
				reasons.add("your best spot");
			}
		}

		String travelLabel = null;
		int bestHops = 99;
		if (entry != null)
		{
			for (TravelData.Teleport t : entry.getTeleports())
			{
				int hops = t.getHops();
				boolean have;
				if (t.getPoh() != null)
				{
					have = t.getItem() != null && t.getPoh().equalsIgnoreCase("Jewellery Box")
						? account.jewelleryBoxCovers(t.getItem()) : account.hasHouseFacility(t.getPoh());
					if (have && !account.canTeleportHome())
					{
						hops += 1;
					}
				}
				else if (t.getItem() != null)
				{
					have = account.ownsItem(t.getItem());
				}
				else if (t.getFairy() != null)
				{
					have = account.fairyRingsUsable();
				}
				else if (t.getSpell() != null)
				{
					have = (t.getQuest() == null || account.questFinished(t.getQuest()))
						&& (t.getLevel() <= 0 || account.skillLevel("MAGIC") < 0 || account.skillLevel("MAGIC") >= t.getLevel());
					int book = bookIndex(t.getBook());
					if (have && book >= 0 && account.spellbook() >= 0 && account.spellbook() != book)
					{
						hops += 1; // needs a spellbook swap first
					}
				}
				else
				{
					have = false;
				}
				if (have && hops < bestHops)
				{
					bestHops = hops;
					travelLabel = t.label();
				}
			}
		}
		if (travelLabel != null)
		{
			score += bestHops <= 1 ? 25 : bestHops == 2 ? 15 : 5;
			reasons.add(travelLabel + (bestHops <= 1 ? "" : bestHops == 2 ? " + short run" : " + long run"));
		}
		else if (entry != null && !entry.getTeleports().isEmpty())
		{
			reasons.add("no teleport you own");
		}

		if (wild)
		{
			reasons.add("Wilderness");
			if (opt.avoidWilderness)
			{
				score -= 40;
			}
		}
		if (locked)
		{
			score -= 100;
		}
		return new ScoredLocation(loc, score, locked, wild, travelLabel, reasons, own);
	}

	/** Region ids with y >= 3520 inside the Wilderness x band. */
	static boolean isWilderness(LocationRecord loc)
	{
		if (loc.getName() != null && loc.getName().toLowerCase(java.util.Locale.ROOT).contains("wilderness"))
		{
			return true;
		}
		if (loc.getRegions() == null)
		{
			return false;
		}
		for (int r : loc.getRegions())
		{
			int rx = r >> 8;
			int ry = r & 0xFF;
			// surface Wilderness: x 2944..3391 (columns 46..52), y 3520..3967 (rows 55..61); column 53 is Morytania
			if (ry >= 55 && ry <= 61 && rx >= 46 && rx <= 52)
			{
				return true;
			}
		}
		return false;
	}

	static int bookIndex(String book)
	{
		if (book == null)
		{
			return -1;
		}
		switch (book.toLowerCase())
		{
			case "standard":
				return 0;
			case "ancient":
				return 1;
			case "lunar":
				return 2;
			case "arceuus":
				return 3;
			default:
				return -1;
		}
	}

	static String pretty(String constant)
	{
		String s = constant.toLowerCase().replace("__", ": ").replace('_', ' ');
		return Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}
}

package com.slayersuite.advisor;

import com.slayersuite.SlayerSuiteConfig;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * A checklist of enabled plugins that do what Slayer Suite does, so you can search the plugin
 * list and switch them off one by one. It rescans every two seconds and disappears on its own
 * once they are all off.
 */
public class OverlapOverlay extends OverlayPanel
{
	private static final Color ACCENT = new Color(255, 176, 0);
	private static final Color DIM = new Color(170, 170, 170);
	private static final long RESCAN_MS = 2000;

	private final Client client;
	private final PluginOverlap overlap;
	private final SlayerSuiteConfig config;
	private long lastScan;

	@Inject
	public OverlapOverlay(Client client, PluginOverlap overlap, SlayerSuiteConfig config)
	{
		this.client = client;
		this.overlap = overlap;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
		panelComponent.setPreferredSize(new Dimension(330, 0));
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.overlapNotice() || client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}
		long now = System.currentTimeMillis();
		if (now - lastScan > RESCAN_MS)
		{
			lastScan = now;
			overlap.scan();
		}
		List<String> active = overlap.active();
		if (active.isEmpty())
		{
			return null;
		}
		panelComponent.getChildren().add(TitleComponent.builder().text("Slayer Suite does these jobs now").color(ACCENT).build());
		panelComponent.getChildren().add(LineComponent.builder().left("Turn these plugins off to avoid doubled overlays and alerts:").leftColor(Color.WHITE).build());
		for (String s : active)
		{
			int i = s.indexOf(':');
			String name = i > 0 ? s.substring(0, i) : s;
			String why = i > 0 ? s.substring(i + 1).trim() : "";
			panelComponent.getChildren().add(LineComponent.builder().left("  " + name).leftColor(Color.WHITE).right("on").rightColor(new Color(255, 90, 90)).build());
			if (!why.isEmpty())
			{
				panelComponent.getChildren().add(LineComponent.builder().left("     " + why).leftColor(DIM).build());
			}
		}
		panelComponent.getChildren().add(LineComponent.builder().left("This notice goes away by itself once they are off. To hide it instead: Slayer Suite settings, Overlapping plugins notice.").leftColor(DIM).build());
		return super.render(g);
	}
}

package com.slayersuite.advisor;

import com.slayersuite.SlayerSuiteConfig;
import com.slayersuite.task.SlayerMode;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.CollisionData;
import net.runelite.api.GameState;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Tiles on the floor from you toward the pinned spot, through the loaded map's
 * walls and obstacles. Far away it leads to the edge of the loaded area in the
 * right direction; the teleport step and the minimap arrow cover the rest.
 */
public class PathOverlay extends Overlay
{
	private static final Color FILL = new Color(80, 220, 255, 60);
	private static final Color EDGE = new Color(80, 220, 255, 160);
	private static final Color END = new Color(255, 215, 80, 200);
	private static final Color BLOCKED = new Color(255, 90, 90, 200);

	private final Client client;
	private final Advisor advisor;
	private final SlayerSuiteConfig config;
	private final SlayerMode mode;

	private volatile List<WorldPoint> path = Collections.emptyList();
	/** True when the line reaches a spawn point; false when it stops short at a door, shortcut, stairs or the edge. */
	@lombok.Getter
	private volatile boolean reachesTarget;
	private int lastSx = -1;
	private int lastSy = -1;
	private WorldPoint lastDest;

	@Inject
	public PathOverlay(Client client, Advisor advisor, SlayerSuiteConfig config, SlayerMode mode)
	{
		this.client = client;
		this.advisor = advisor;
		this.config = config;
		this.mode = mode;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_LOW);
	}

	/** Non-empty while the line stops short of the spot. */
	public boolean blocked()
	{
		return !path.isEmpty() && !reachesTarget && advisor.getDestination() != null && !advisor.isArrived();
	}

	@Subscribe
	public void onGameTick(GameTick t)
	{
		if (!config.floorPath() || client.getGameState() != GameState.LOGGED_IN)
		{
			path = Collections.emptyList();
			return;
		}
		WorldPoint dest = advisor.destinationPoint();
		Player me = client.getLocalPlayer();
		WorldView wv = client.getTopLevelWorldView();
		if (dest == null || advisor.isArrived() || me == null || wv == null || !mode.active())
		{
			path = Collections.emptyList();
			lastDest = null;
			return;
		}
		LocalPoint lp = me.getLocalLocation();
		if (lp == null)
		{
			return;
		}
		int sx = lp.getSceneX();
		int sy = lp.getSceneY();
		if (sx == lastSx && sy == lastSy && dest.equals(lastDest) && !path.isEmpty())
		{
			return;
		}
		lastSx = sx;
		lastSy = sy;
		lastDest = dest;
		path = compute(wv, me.getWorldLocation(), sx, sy, dest);
	}

	private List<WorldPoint> compute(WorldView wv, WorldPoint here, int sx, int sy, WorldPoint dest)
	{
		CollisionData[] maps = wv.getCollisionMaps();
		int plane = wv.getPlane();
		if (maps == null || plane < 0 || plane >= maps.length || maps[plane] == null)
		{
			return Collections.emptyList();
		}
		int[][] raw = maps[plane].getFlags();
		if (raw == null || raw.length == 0)
		{
			return Collections.emptyList();
		}
		int size = raw.length;
		// Tiles that do not exist (the empty part of a house or dungeon instance) read as open; treat them as walls.
		int[][] flags = new int[size][];
		Scene scene = wv.getScene();
		Tile[][][] sceneTiles = scene == null ? null : scene.getTiles();
		for (int x = 0; x < size; x++)
		{
			flags[x] = raw[x].clone();
			if (sceneTiles != null && plane < sceneTiles.length && sceneTiles[plane] != null && x < sceneTiles[plane].length)
			{
				for (int y = 0; y < flags[x].length; y++)
				{
					if (y >= sceneTiles[plane][x].length || sceneTiles[plane][x][y] == null)
					{
						flags[x][y] |= CollisionDataFlag.BLOCK_MOVEMENT_FULL;
					}
				}
			}
		}
		int baseX = wv.getBaseX();
		int baseY = wv.getBaseY();
		int tx = dest.getX() - baseX;
		int ty = dest.getY() - baseY;
		boolean inScene = tx >= 0 && ty >= 0 && tx < size && ty < size && dest.getPlane() == plane;
		// Prefer the nearest reachable spawn pin over the middle of the spawn cloud.
		com.slayersuite.data.LocationRecord loc = advisor.getDestination();
		if (loc != null && loc.getPins() != null && !loc.getPins().isEmpty() && dest.getPlane() == plane)
		{
			int[][] dist = ScenePath.distances(flags, sx, sy);
			int bestD = Integer.MAX_VALUE;
			int bx = -1;
			int by = -1;
			for (List<Integer> pin : loc.getPins())
			{
				if (pin == null || pin.size() < 2)
				{
					continue;
				}
				int px = pin.get(0) - baseX;
				int py = pin.get(1) - baseY;
				if (px < 0 || py < 0 || px >= size || py >= size || dist[px][py] < 0)
				{
					continue;
				}
				if (dist[px][py] < bestD)
				{
					bestD = dist[px][py];
					bx = px;
					by = py;
				}
			}
			if (bx >= 0)
			{
				tx = bx;
				ty = by;
				inScene = true;
			}
		}
		if (!inScene)
		{
			// Far away, or inside an instance (your house, a dungeon): the teleport step and the arrow are the route.
			double dx = dest.getX() - here.getX();
			double dy = dest.getY() - here.getY();
			double len = Math.hypot(dx, dy);
			if (len < 1 || len > config.floorPathMaxDistance() || wv.isInstance())
			{
				return Collections.emptyList();
			}
			int reach = Math.min((int) len, 48);
			tx = clamp(sx + (int) Math.round(dx / len * reach), 1, size - 2);
			ty = clamp(sy + (int) Math.round(dy / len * reach), 1, size - 2);
		}
		List<int[]> tiles = ScenePath.find(flags, sx, sy, tx, ty, config.floorPathTiles());
		reachesTarget = inScene && !tiles.isEmpty() && tiles.get(tiles.size() - 1)[0] == tx && tiles.get(tiles.size() - 1)[1] == ty;
		List<WorldPoint> out = new ArrayList<>(tiles.size());
		for (int[] tile : tiles)
		{
			out.add(new WorldPoint(tile[0] + baseX, tile[1] + baseY, plane));
		}
		return out;
	}

	private static int clamp(int v, int lo, int hi)
	{
		return Math.max(lo, Math.min(hi, v));
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		List<WorldPoint> p = path;
		if (p.size() < 2 || !config.floorPath())
		{
			return null;
		}
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return null;
		}
		g.setStroke(new BasicStroke(1f));
		for (int i = 1; i < p.size(); i++)
		{
			LocalPoint lp = LocalPoint.fromWorld(wv, p.get(i));
			if (lp == null)
			{
				continue;
			}
			Polygon poly = Perspective.getCanvasTilePoly(client, lp);
			if (poly == null)
			{
				continue;
			}
			boolean last = i == p.size() - 1;
			Color endColor = reachesTarget ? END : BLOCKED;
			g.setColor(last ? endColor : FILL);
			g.fillPolygon(poly);
			g.setColor(last ? endColor : EDGE);
			g.drawPolygon(poly);
		}
		return null;
	}
}

package com.slayersuite.advisor;

import com.slayersuite.SlayerSuiteConfig;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;

/** Spots other enabled plugins that do what this one does: a chat line once per login, the on-screen checklist, and a card in the panel. */
@Singleton
public class PluginOverlap
{
	/** Plugin class name -> what overlaps. */
	private static final Map<String, String> KNOWN = new LinkedHashMap<>();

	static
	{
		KNOWN.put("com.slayereta.SlayerEtaPlugin", "Slayer Task ETA: the card has the ETA, rate and done-at clock");
		KNOWN.put("com.slayerscapetarget.SlayerScapeTargetPlugin", "Slayer Scape Target: the attack guard does this");
		KNOWN.put("com.taskjingle.TaskJinglePlugin", "TaskJingle: task and level-up sounds are built in");
		KNOWN.put("com.slayeritemreminders.SlayerItemRemindersPlugin", "Slayer Item Reminders: the readiness check covers herb sack and seed box");
		KNOWN.put("com.afkingtoolkit.AfkingToolkitPlugin", "AFKing Toolkit: its alerts double up with the alert engine (its screen dim does not)");
	}

	private final Client client;
	private final PluginManager pluginManager;
	private final SlayerSuiteConfig config;

	private boolean announced;
	private int tick;
	private volatile List<String> active = new ArrayList<>();

	@Inject
	public PluginOverlap(Client client, PluginManager pluginManager, SlayerSuiteConfig config)
	{
		this.client = client;
		this.pluginManager = pluginManager;
		this.config = config;
	}

	public void reset()
	{
		announced = false;
		active = new ArrayList<>();
	}

	/** Display lines for every overlapping plugin that is currently on. */
	public List<String> active()
	{
		return active;
	}

	/** True when a plugin whose class name starts with the prefix is loaded (installed), enabled or not. */
	public boolean hasPlugin(String classPrefix)
	{
		try
		{
			for (Plugin p : pluginManager.getPlugins())
			{
				if (p.getClass().getName().startsWith(classPrefix))
				{
					return true;
				}
			}
		}
		catch (RuntimeException e)
		{
			// unknown
		}
		return false;
	}

	public List<String> scan()
	{
		List<String> out = new ArrayList<>();
		try
		{
			for (Plugin p : pluginManager.getPlugins())
			{
				String what = KNOWN.get(p.getClass().getName());
				if (what != null && pluginManager.isPluginEnabled(p))
				{
					out.add(what);
				}
			}
		}
		catch (RuntimeException e)
		{
			// plugin list unavailable; nothing to say
		}
		active = out;
		return out;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOGIN_SCREEN)
		{
			announced = false;
		}
	}

	@Subscribe
	public void onGameTick(GameTick t)
	{
		if (++tick % 50 != 0)
		{
			return;
		}
		List<String> now = scan();
		if (!announced && config.overlapNotice() && !now.isEmpty() && client.getGameState() == GameState.LOGGED_IN)
		{
			announced = true;
			List<String> names = new ArrayList<>();
			for (String s : now)
			{
				names.add(s.substring(0, s.indexOf(':')));
			}
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "<col=ffb000>Slayer Suite:</col> these plugins do jobs it now does: " + String.join(", ", names) + ". The checklist at the top of the screen clears itself as you turn them off.", null);
		}
	}
}

package com.slayersuite.advisor;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.api.CollisionDataFlag;

/**
 * Breadth-first path over the loaded scene's collision flags. Walls, objects and
 * water are respected; doors, stairs and shortcuts are not (a closed door is a
 * wall). When the target is not reachable it paths to the reachable tile
 * nearest to it, so the line always points the right way.
 */
public final class ScenePath
{
	private static final int BLOCKED = CollisionDataFlag.BLOCK_MOVEMENT_FULL | CollisionDataFlag.BLOCK_MOVEMENT_FLOOR
		| CollisionDataFlag.BLOCK_MOVEMENT_OBJECT | CollisionDataFlag.BLOCK_MOVEMENT_FLOOR_DECORATION;

	private ScenePath()
	{
	}

	/** Scene coordinates from start (inclusive) to the end tile. Empty when the start is off the grid. */
	public static List<int[]> find(int[][] flags, int sx, int sy, int tx, int ty, int maxTiles)
	{
		if (flags == null || flags.length == 0 || !inside(flags, sx, sy))
		{
			return Collections.emptyList();
		}
		int w = flags.length;
		int h = flags[0].length;
		int[] prev = new int[w * h];
		java.util.Arrays.fill(prev, -1);
		boolean[] seen = new boolean[w * h];
		ArrayDeque<Integer> queue = new ArrayDeque<>();
		int start = sx * h + sy;
		seen[start] = true;
		queue.add(start);
		int best = start;
		double bestDist = dist(sx, sy, tx, ty);
		int expanded = 0;
		while (!queue.isEmpty() && expanded < w * h)
		{
			int cur = queue.poll();
			expanded++;
			int cx = cur / h;
			int cy = cur % h;
			double d = dist(cx, cy, tx, ty);
			if (d < bestDist)
			{
				bestDist = d;
				best = cur;
			}
			if (cx == tx && cy == ty)
			{
				break;
			}
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					if (dx == 0 && dy == 0)
					{
						continue;
					}
					int nx = cx + dx;
					int ny = cy + dy;
					if (!inside(flags, nx, ny) || seen[nx * h + ny] || !canStep(flags, cx, cy, dx, dy))
					{
						continue;
					}
					seen[nx * h + ny] = true;
					prev[nx * h + ny] = cur;
					queue.add(nx * h + ny);
				}
			}
		}
		List<int[]> path = new ArrayList<>();
		for (int at = best; at != -1; at = prev[at])
		{
			path.add(new int[]{at / h, at % h});
			if (at == start)
			{
				break;
			}
		}
		Collections.reverse(path);
		if (path.size() > maxTiles)
		{
			return new ArrayList<>(path.subList(0, maxTiles));
		}
		return path;
	}

	/** BFS distance from the start to every tile; -1 where unreachable. */
	public static int[][] distances(int[][] flags, int sx, int sy)
	{
		int w = flags.length;
		int h = flags[0].length;
		int[][] dist = new int[w][h];
		for (int[] row : dist)
		{
			java.util.Arrays.fill(row, -1);
		}
		if (!inside(flags, sx, sy))
		{
			return dist;
		}
		ArrayDeque<int[]> queue = new ArrayDeque<>();
		dist[sx][sy] = 0;
		queue.add(new int[]{sx, sy});
		while (!queue.isEmpty())
		{
			int[] c = queue.poll();
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					if (dx == 0 && dy == 0)
					{
						continue;
					}
					int nx = c[0] + dx;
					int ny = c[1] + dy;
					if (inside(flags, nx, ny) && dist[nx][ny] < 0 && canStep(flags, c[0], c[1], dx, dy))
					{
						dist[nx][ny] = dist[c[0]][c[1]] + 1;
						queue.add(new int[]{nx, ny});
					}
				}
			}
		}
		return dist;
	}

	static boolean inside(int[][] flags, int x, int y)
	{
		return x >= 0 && y >= 0 && x < flags.length && y < flags[0].length;
	}

	static boolean blocked(int[][] flags, int x, int y)
	{
		return (flags[x][y] & BLOCKED) != 0;
	}

	/** One step from (x,y) by (dx,dy), with OSRS's rule that a diagonal needs both cardinals free. */
	static boolean canStep(int[][] flags, int x, int y, int dx, int dy)
	{
		int nx = x + dx;
		int ny = y + dy;
		if (!inside(flags, nx, ny) || blocked(flags, nx, ny))
		{
			return false;
		}
		if (dx != 0 && dy != 0)
		{
			return canStep(flags, x, y, dx, 0) && canStep(flags, x, y, 0, dy)
				&& canStep(flags, x + dx, y, 0, dy) && canStep(flags, x, y + dy, dx, 0);
		}
		int from = flags[x][y];
		int to = flags[nx][ny];
		if (dx == 1)
		{
			return (from & CollisionDataFlag.BLOCK_MOVEMENT_EAST) == 0 && (to & CollisionDataFlag.BLOCK_MOVEMENT_WEST) == 0;
		}
		if (dx == -1)
		{
			return (from & CollisionDataFlag.BLOCK_MOVEMENT_WEST) == 0 && (to & CollisionDataFlag.BLOCK_MOVEMENT_EAST) == 0;
		}
		if (dy == 1)
		{
			return (from & CollisionDataFlag.BLOCK_MOVEMENT_NORTH) == 0 && (to & CollisionDataFlag.BLOCK_MOVEMENT_SOUTH) == 0;
		}
		return (from & CollisionDataFlag.BLOCK_MOVEMENT_SOUTH) == 0 && (to & CollisionDataFlag.BLOCK_MOVEMENT_NORTH) == 0;
	}

	private static double dist(int x, int y, int tx, int ty)
	{
		return Math.hypot(tx - x, ty - y);
	}
}

