	/** RuneLite's own scroll pane around this panel, found once it exists. */
	private JScrollPane scroll()
	{
		java.awt.Container c = getParent();
		while (c != null)
		{
			if (c instanceof JScrollPane)
			{
				return (JScrollPane) c;
			}
			c = c.getParent();
		}
		return null;
	}

	private final Advisor advisor;
