/**
 * Scans worn equipment, the inventory and (while open) the bank, and compares
 * them with the task record's item rules. Read-only: it never moves an item.
 */
@Singleton
public class ReadinessChecker
{
	private final Client client;
	/** Prayer points this task has cost per kill in your history, pushed by the trip tracker each tick (no injection cycle). */
	private volatile double prayerPerKill;
	private final ItemManager itemManager;
	private final SlayerDataset dataset;
	private final TaskTracker tracker;
	private final SlayerSuiteConfig config;
	private final Provider<Advisor> advisor;
	private final Provider<AccountState> account;
	private final TravelData travel;
	private final ConfigManager configManager;
	private final Gson gson;

	private static final String OWNED_KEY = "ownedItems";
	private static final Pattern DEAD_SUFFIX = Pattern.compile("\\((inert|uncharged|empty|broken|0)\\)");
	/** Normalised names of teleport and task items seen in the bank in any session, saved on the profile. */
	private final Set<String> remembered = new TreeSet<>();
	private boolean rememberedLoaded;
	private Set<String> relevant;

	private final Map<Integer, String> nameCache = new HashMap<>();
	private final Map<Integer, Boolean> edibleCache = new HashMap<>();

	private final Set<String> held = new HashSet<>();
	private final Set<String> bankNames = new HashSet<>();
	@Getter
	private int foodCount;
	@Getter
	private long bankSeenAt;
	@Getter
	private boolean bankOpen;
	@Getter
	private List<Missing> missing = Collections.emptyList();
	private boolean dirty = true;

	@Inject
	public ReadinessChecker(Client client, ItemManager itemManager, SlayerDataset dataset, TaskTracker tracker, SlayerSuiteConfig config,
		Provider<Advisor> advisor, Provider<AccountState> account, TravelData travel, ConfigManager configManager, Gson gson)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.dataset = dataset;
		this.tracker = tracker;
		this.config = config;
		this.advisor = advisor;
		this.account = account;
		this.travel = travel;
		this.configManager = configManager;
		this.gson = gson;
	}

	/** Names worth remembering across sessions: every teleport item in travel.json and every item group member. */
	private Set<String> relevantNames()
	{
		if (relevant == null)
		{
			Set<String> r = new HashSet<>();
			for (String n : travel.itemNames())
			{
				r.add(ItemNames.normalize(n));
			}
			for (String key : dataset.getItems().keys())
			{
				ItemGroups.Group g = dataset.getItems().get(key);
				if (g != null)
				{
					for (String n : g.getNames())
					{
						r.add(ItemNames.normalize(n));
					}
				}
			}
			for (String n : new String[]{"Teleport to house", "Construction cape", "Max cape"})
			{
				r.add(ItemNames.normalize(n));
			}
			relevant = r;
		}
		return relevant;
	}

	private void loadRemembered()
	{
		remembered.clear();
		try
		{
			String json = configManager.getRSProfileConfiguration(SlayerSuiteConfig.GROUP, OWNED_KEY);
			if (json != null && !json.isEmpty())
			{
				List<String> list = gson.fromJson(json, new TypeToken<List<String>>()
				{
				}.getType());
				if (list != null)
				{
					remembered.addAll(list);
				}
			}
		}
		catch (RuntimeException e)
		{
			// nothing remembered
		}
		rememberedLoaded = true;
	}

	private void rememberBank()
	{
		if (configManager.getRSProfileKey() == null)
		{
			return;
		}
		if (!rememberedLoaded)
		{
			loadRemembered();
		}
		Set<String> rel = relevantNames();
		boolean changed = false;
		for (String n : bankNames)
		{
			if (matchesRelevant(n, rel) && remembered.add(n))
			{
				changed = true;
			}
		}
		for (String n : held)
		{
			if (matchesRelevant(n, rel) && remembered.add(n))
			{
				changed = true;
			}
		}
		if (changed)
		{
			try
			{
				configManager.setRSProfileConfiguration(SlayerSuiteConfig.GROUP, OWNED_KEY, gson.toJson(new ArrayList<>(remembered)));
			}
			catch (RuntimeException e)
			{
				// ignore
			}
		}
	}

	private static boolean matchesRelevant(String normalised, Set<String> rel)
	{
		if (rel.contains(normalised))
		{
			return true;
		}
		for (String r : rel)
		{
			if (normalised.startsWith(r + " ") || normalised.startsWith(r + "("))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * You own the item: carried or worn now, seen in the bank this session, or seen in any earlier
	 * session. Charge variants count ("Slayer ring (eternal)"), dead ones do not ("(inert)", "(uncharged)").
	 */
	public boolean owns(String itemName)
	{
		if (!rememberedLoaded && client.getGameState() == GameState.LOGGED_IN)
		{
			loadRemembered();
		}
		String want = ItemNames.normalize(itemName);
		if (want.isEmpty())
		{
			return false;
		}
		for (Set<String> pool : java.util.Arrays.asList(held, bankNames, remembered))
		{
			if (pool.contains(want))
			{
				return true;
			}
			for (String have : pool)
			{
				if ((have.startsWith(want + " ") || have.startsWith(want + "(")) && !DEAD_SUFFIX.matcher(have).find())
				{
					return true;
				}
			}
		}
		return false;
	}

	public boolean anythingRemembered()
	{
		return bankSeenAt > 0 || !remembered.isEmpty();
	}

	public void setPrayerPerKill(double perKill)
	{
		prayerPerKill = perKill;
	}

	public void reset()
	{
		held.clear();
		bankNames.clear();
		foodCount = 0;
		bankOpen = false;
		missing = Collections.emptyList();
		dirty = true;
	}

	public boolean hasGroup(String groupKey)
	{
		return dataset.getItems().satisfied(groupKey, held);
	}

	public boolean holds(String itemName)
	{
		return held.contains(ItemNames.normalize(itemName));
	}

	public Set<String> heldNames()
	{
		return Collections.unmodifiableSet(held);
	}

	/** Normalised names of everything seen in the bank the last time it was open. */
	public Set<String> bankNames()
	{
		return Collections.unmodifiableSet(bankNames);
	}

	public List<Missing> requiredMissing()
	{
		List<Missing> out = new ArrayList<>();
		for (Missing m : missing)
		{
			if (m.isRequired())
			{
				out.add(m);
			}
		}
		return out;
	}

	public boolean isReady()
	{
		return requiredMissing().isEmpty();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOGGED_IN)
		{
			dirty = true;
		}
		else if (e.getGameState() == GameState.LOGIN_SCREEN)
		{
			bankOpen = false;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged e)
	{
		int id = e.getContainerId();
		if (id == InventoryID.INV || id == InventoryID.WORN)
		{
			rescanHeld();
			dirty = true;
		}
		else if (id == InventoryID.BANK)
		{
			rescanBank(e.getItemContainer());
			dirty = true;
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded e)
	{
		if (e.getGroupId() == InterfaceID.BANKMAIN)
		{
			bankOpen = true;
			ItemContainer bank = client.getItemContainer(InventoryID.BANK);
			if (bank != null)
			{
				rescanBank(bank);
			}
			rescanHeld();
			dirty = true;
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed e)
	{
		if (e.getGroupId() == InterfaceID.BANKMAIN)
		{
			bankOpen = false;
			dirty = true;
		}
	}

	@Subscribe
	public void onTaskChanged(TaskChanged e)
	{
		dirty = true;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (dirty)
		{
			if (held.isEmpty() && foodCount == 0)
			{
				rescanHeld();
			}
			recompute();
			dirty = false;
		}
	}

	private void rescanHeld()
	{
		held.clear();
		foodCount = 0;
		scanInto(client.getItemContainer(InventoryID.INV), held, true);
		scanInto(client.getItemContainer(InventoryID.WORN), held, false);
	}

	private void rescanBank(ItemContainer bank)
	{
		bankNames.clear();
		scanInto(bank, bankNames, false);
		bankSeenAt = System.currentTimeMillis();
		rememberBank();
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged e)
	{
		rememberedLoaded = false;
	}

	private void scanInto(ItemContainer container, Set<String> names, boolean countFood)
	{
		if (container == null)
		{
			return;
		}
		for (Item item : container.getItems())
		{
			if (item == null || item.getId() <= 0)
			{
				continue;
			}
			int id = item.getId();
			String name = nameCache.get(id);
			Boolean edible = edibleCache.get(id);
			if (name == null || edible == null)
			{
				ItemComposition comp = itemManager.getItemComposition(id);
				name = ItemNames.normalize(comp.getName());
				edible = hasAction(comp, "Eat");
				nameCache.put(id, name);
				edibleCache.put(id, edible);
			}
			names.add(name);
			if (countFood && edible)
			{
				foodCount += Math.max(1, item.getQuantity());
			}
		}
	}

	/** You carry a cannon: say when it cannot be used where you are, or where you are going. */
	private void cannonWarnings(TaskRecord rec, List<Missing> out)
	{
		try
		{
			if (!account.get().questFinished("DWARF_CANNON") && client.getGameState() == net.runelite.api.GameState.LOGGED_IN)
			{
				out.add(new Missing("Dwarf Cannon quest", "you cannot set a cannon up before finishing it", false, false));
			}
		}
		catch (RuntimeException e)
		{
			// quest state unavailable; say nothing
		}
		boolean immune = rec != null && rec.cannonImmune();
		LocationRecord here = tracker.getCurrentLocation();
		if (here != null)
		{
			if (immune)
			{
				out.add(new Missing("Cannon is useless here", "the monsters are immune to cannon damage", false, false));
			}
			else if (Boolean.FALSE.equals(here.getCannon()))
			{
				out.add(new Missing("Cannon cannot be placed here", here.getName() + " does not allow one", false, false));
			}
			return;
		}
		if (bankOpen)
		{
			Advisor a = advisor.get();
			LocationRecord dest = a.getDestination();
			if (dest == null)
			{
				ScoredLocation best = a.best();
				dest = best == null ? null : best.getLocation();
			}
			if (dest != null)
			{
				if (immune)
				{
					out.add(new Missing("Leave the cannon", "the task monsters are immune to it", false, false));
				}
				else if (Boolean.FALSE.equals(dest.getCannon()))
				{
					out.add(new Missing("Leave the cannon", dest.getName() + " does not allow one", false, false));
				}
			}
		}
	}

	private static boolean hasAction(ItemComposition comp, String action)
	{
		String[] actions = comp.getInventoryActions();
		if (actions == null)
		{
			return false;
		}
		for (String a : actions)
		{
			if (action.equalsIgnoreCase(a))
			{
				return true;
			}
		}
		return false;
	}

	private void recompute()
	{
		TaskRecord rec = tracker.getRecord();
		if (!tracker.hasTask())
		{
			missing = Collections.emptyList();
			return;
		}
		ItemGroups items = dataset.getItems();
		List<Missing> out = new ArrayList<>();
		boolean hasPoisonRule = false;
		if (rec != null)
		{
			for (ItemRule rule : rec.allRules())
			{
				List<String> groups = rule.getAnyOf();
				if (groups == null || groups.isEmpty())
				{
					continue;
				}
				if (groups.contains("antipoison") || groups.contains("antivenom"))
				{
					hasPoisonRule = true;
				}
				if (!rule.isRequired() && !config.readinessRecommended())
				{
					continue;
				}
				if (!items.anySatisfied(groups, held))
				{
					out.add(new Missing(items.describe(groups), rule.getWhy(), rule.isRequired(), items.anySatisfied(groups, bankNames)));
				}
			}
			if (!hasPoisonRule && config.readinessRecommended() && rec.anyPoisonous() && !items.satisfied("antipoison", held))
			{
				String key = rec.anyVenomous() ? "antivenom" : "antipoison";
				out.add(new Missing(items.label(key), rec.anyVenomous() ? "the monsters inflict venom" : "the monsters poison", false, items.satisfied(key, bankNames)));
			}
			if (config.readinessPrayer() && prayerPerKill > 0.2 && !items.satisfied("prayer_restore", held))
			{
				out.add(new Missing(items.label("prayer_restore"), "this task has cost you prayer points before", false, items.satisfied("prayer_restore", bankNames)));
			}
		}
		if (config.readinessFood() && foodCount == 0)
		{
			out.add(new Missing("Food", "nothing edible in your inventory", false, true));
		}
		if (config.readinessCannon() && items.satisfied("cannon_parts", held))
		{
			if (!items.satisfied("cannonballs", held))
			{
				out.add(new Missing(items.label("cannonballs"), "you carry a cannon", true, items.satisfied("cannonballs", bankNames)));
			}
			cannonWarnings(rec, out);
		}
		missing = out;
	}
}

package com.slayersuite.readiness;

import com.slayersuite.SlayerSuiteConfig;
import com.slayersuite.data.ItemGroups;
import com.slayersuite.data.ItemRule;
import com.slayersuite.data.SlayerDataset;
import com.slayersuite.data.TaskRecord;
import com.slayersuite.task.TaskTracker;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/** The "you have everything for this task" list, shown while the bank is open. */
public class ReadinessOverlay extends OverlayPanel
{
	private static final Color OK = new Color(120, 220, 120);
	private static final Color MISSING = new Color(255, 90, 90);
	private static final Color RECOMMENDED = new Color(255, 200, 80);
	private static final Color DIM = new Color(170, 170, 170);

	private final ReadinessChecker checker;
	private final TaskTracker tracker;
	private final SlayerDataset dataset;
	private final SlayerSuiteConfig config;
	private final com.slayersuite.task.SlayerMode mode;
	private final com.slayersuite.history.TaskHistory history;
	private final com.slayersuite.trip.TripTracker trip;
	private final net.runelite.api.Client client;

	@Inject
	public ReadinessOverlay(ReadinessChecker checker, TaskTracker tracker, SlayerDataset dataset, SlayerSuiteConfig config, com.slayersuite.task.SlayerMode mode,
		com.slayersuite.history.TaskHistory history, com.slayersuite.trip.TripTracker trip, net.runelite.api.Client client)
	{
		this.history = history;
		this.trip = trip;
		this.client = client;
		this.mode = mode;
		this.checker = checker;
		this.tracker = tracker;
		this.dataset = dataset;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(PRIORITY_HIGH);
		panelComponent.setPreferredSize(new Dimension(230, 0));
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.readinessOverlay() || !checker.isBankOpen() || !tracker.hasTask() || (!mode.active() && !mode.helmWithYou()))
		{
			return null;
		}
		TaskRecord rec = tracker.getRecord();
		String title = rec != null ? rec.title() : tracker.getTaskName();
		boolean ready = checker.isReady();
		panelComponent.getChildren().add(TitleComponent.builder()
			.text((ready ? "Ready: " : "Not ready: ") + title)
			.color(ready ? OK : MISSING)
			.build());

		if (rec == null)
		{
			panelComponent.getChildren().add(LineComponent.builder().left("No dataset entry for this task yet.").leftColor(DIM).build());
		}
		else
		{
			ItemGroups items = dataset.getItems();
			for (ItemRule rule : rec.allRules())
			{
				if (!rule.isRequired() || rule.getAnyOf() == null || !items.anySatisfied(rule.getAnyOf(), checker.heldNames()))
				{
					continue;
				}
				String heldName = items.heldName(rule.getAnyOf(), checker.heldNames());
				panelComponent.getChildren().add(LineComponent.builder()
					.left(heldName == null ? items.describe(rule.getAnyOf()) : heldName)
					.leftColor(OK)
					.right("ok")
					.rightColor(OK)
					.build());
			}
		}
		for (Missing m : checker.getMissing())
		{
			Color c = m.isRequired() ? MISSING : RECOMMENDED;
			panelComponent.getChildren().add(LineComponent.builder()
				.left((m.isRequired() ? "Missing: " : "Bring: ") + m.getLabel())
				.leftColor(c)
				.right(m.isInBank() ? "in bank" : "")
				.rightColor(DIM)
				.build());
			if (m.getWhy() != null && !m.getWhy().isEmpty())
			{
				panelComponent.getChildren().add(LineComponent.builder().left("  " + m.getWhy()).leftColor(DIM).build());
			}
		}
		packingList();
		return super.render(g);
	}

	/** What to take for the kills left, from your own rates on this task. */
	private void packingList()
	{
		int remaining = tracker.getRemaining();
		com.slayersuite.history.TaskStats stats = history.getCurrent();
		if (remaining <= 0)
		{
			return;
		}
		boolean session = trip.getSessionKills() >= 5;
		double fpk = session ? trip.foodPerKill() : stats == null ? 0 : stats.getFoodPerKill();
		double ppk = session ? trip.prayerPerKill() : stats == null ? 0 : stats.getPrayerPerKill();
		double dpk = session ? trip.dosesPerKill() : stats == null ? 0 : stats.getDosesPerKill();
		double antifireMin = 0;
		if (trip.taskNeedsAntifire() && tracker.effectiveKph() > 0)
		{
			antifireMin = remaining / tracker.effectiveKph() * 60.0;
		}
		if (fpk <= 0 && ppk <= 0 && dpk <= 0 && antifireMin <= 0)
		{
			panelComponent.getChildren().add(LineComponent.builder().left("Pack: no rates for this task yet").leftColor(DIM).build());
			return;
		}
		int level = client.getGameState() == net.runelite.api.GameState.LOGGED_IN ? client.getRealSkillLevel(net.runelite.api.Skill.PRAYER) : 1;
		com.slayersuite.trip.PackingMath.Pack pack = com.slayersuite.trip.PackingMath.pack(remaining, fpk, ppk, dpk,
			com.slayersuite.trip.TripTracker.prayerPerDose("prayer potion", level), antifireMin, 6, 0.15);
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Pack for " + remaining + " kills").leftColor(Color.WHITE)
			.right(pack.getTrips() <= 1 ? "one trip" : pack.getTrips() + " trips").rightColor(pack.getTrips() <= 1 ? OK : RECOMMENDED).build());
		if (pack.getFood() > 0)
		{
			panelComponent.getChildren().add(LineComponent.builder().left("  Food").leftColor(DIM).right(pack.getFood() + " pieces").rightColor(Color.WHITE).build());
		}
		if (pack.getPrayerDoses() > 0)
		{
			panelComponent.getChildren().add(LineComponent.builder().left("  Prayer").leftColor(DIM).right(pack.getPrayerDoses() + " doses (" + pack.getPrayerPotions() + " potions)").rightColor(Color.WHITE).build());
		}
		if (pack.getOtherDoses() > 0)
		{
			panelComponent.getChildren().add(LineComponent.builder().left("  Other potions").leftColor(DIM).right(pack.getOtherDoses() + " doses (" + pack.getOtherPotions() + ")").rightColor(Color.WHITE).build());
		}
		if (pack.getAntifireDoses() > 0)
		{
			panelComponent.getChildren().add(LineComponent.builder().left("  Antifire").leftColor(DIM).right(pack.getAntifireDoses() + " doses").rightColor(Color.WHITE).build());
		}
		panelComponent.getChildren().add(LineComponent.builder().left("  15% spare, from " + (session ? "this session" : "your history")).leftColor(DIM).build());
	}
}

package com.slayersuite.sounds;

import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.util.Filepath;

/**
 * Plays the bundled chimes, or a player's own file of the same name from the plugin's
 * sounds folder when one exists. The folder comes from RuneLite's plugin directory API.
 */
@Slf4j
@Singleton
public class SoundPlayer
{
	public enum Sound
	{
		TASK_DONE("task-done.wav"),
		SUPERIOR("superior.wav"),
		ALERT("alert.wav"),
		TICK("tick.wav"),
		/** No bundled file: plays only when the player supplies level-up.wav. */
		LEVEL_UP("level-up.wav");

		final String file;

		Sound(String file)
		{
			this.file = file;
		}
	}

	private final AudioPlayer audioPlayer;
	private final ScheduledExecutorService executor;
	private volatile long lastPlayedAt;
	/** The plugin's sounds folder; null until the plugin starts, in which case only bundled sounds play. */
	private volatile Filepath directory;

	@Inject
	public SoundPlayer(AudioPlayer audioPlayer, ScheduledExecutorService executor)
	{
		this.audioPlayer = audioPlayer;
		this.executor = executor;
	}

	public void setDirectory(Filepath directory)
	{
		this.directory = directory;
	}

	public Filepath getDirectory()
	{
		return directory;
	}

	private Filepath custom(Sound sound)
	{
		Filepath dir = directory;
		if (dir == null)
		{
			return null;
		}
		Filepath f = dir.joinSegment(sound.file);
		return f.isFile() ? f : null;
	}

	public void play(Sound sound, int volumePercent)
	{
		if (volumePercent <= 0)
		{
			return;
		}
		if (sound == Sound.LEVEL_UP && custom(sound) == null)
		{
			return;
		}
		long now = System.currentTimeMillis();
		if (now - lastPlayedAt < (sound == Sound.TICK ? 80 : 250))
		{
			return;
		}
		lastPlayedAt = now;
		float gainDb = (float) (20.0 * Math.log10(Math.max(1, Math.min(100, volumePercent)) / 100.0));
		executor.execute(() ->
		{
			try
			{
				Filepath custom = custom(sound);
				if (custom != null)
				{
					audioPlayer.play(custom, gainDb);
				}
				else
				{
					audioPlayer.play(SoundPlayer.class, "/com/slayersuite/sounds/" + sound.file, gainDb);
				}
			}
			catch (Exception e)
			{
				log.warn("Slayer Suite: could not play {} ({})", sound, e.toString());
			}
		});
	}
}

package com.slayersuite.task;

import lombok.Value;

/** Posted once when a brand-new assignment begins (not on login into a task already underway). */
@Value
public class AssignmentStarted
{
	String name;
	int amount;
}

package com.slayersuite.task;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * The game's own slayer tables, read from the client cache: which task the target
 * value means, which area the area value means, and how each master weights
 * its assignments. This is how the client itself names your task, so it works
 * for every master, Mortimer included, with no gem check.
 */
@Slf4j
@Singleton
public class GameTaskTable
{
	/** Target value the game uses for "a boss task"; the boss id then lives in another value. */
	private static final int BOSS_TARGET = 98;

	@Value
	public static class GameTask
	{
		int taskId;
		String name;
		int remaining;
		String area;
		int masterId;
	}

	private final Client client;
	private final Map<Integer, String> nameCache = new LinkedHashMap<>();
	private final Map<Integer, String> areaCache = new LinkedHashMap<>();
	private final Map<Integer, Map<Integer, Integer>> weightCache = new LinkedHashMap<>();

	@Inject
	public GameTaskTable(Client client)
	{
		this.client = client;
	}

	/** The current assignment straight from the game, or null when there is none or the tables are unavailable. */
	public GameTask currentTask()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}
		try
		{
			int remaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
			if (remaining <= 0)
			{
				return null;
			}
			int target = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
			int taskId = target;
			if (target == BOSS_TARGET)
			{
				int bossId = client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID);
				List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTaskSublist.ID, DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID, 0, bossId);
				if (rows == null || rows.isEmpty())
				{
					return null;
				}
				Object[] f = client.getDBTableField(rows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0);
				if (f == null || f.length == 0 || !(f[0] instanceof Integer))
				{
					return null;
				}
				taskId = (Integer) f[0];
			}
			String name = taskName(taskId);
			if (name == null)
			{
				return null;
			}
			String area = null;
			int areaId = client.getVarpValue(VarPlayerID.SLAYER_AREA);
			if (areaId > 0)
			{
				area = areaName(areaId);
			}
			int master = client.getVarbitValue(VarbitID.SLAYER_MASTER);
			return new GameTask(taskId, name, remaining, area, master);
		}
		catch (RuntimeException e)
		{
			log.debug("slayer table lookup failed", e);
			return null;
		}
	}

	/** Display name of a task id from the SlayerTask table, or null. */
	public String taskName(int taskId)
	{
		String cached = nameCache.get(taskId);
		if (cached != null)
		{
			return cached;
		}
		List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
		if (rows == null || rows.isEmpty())
		{
			return null;
		}
		Object[] f = client.getDBTableField(rows.get(0), DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0);
		if (f == null || f.length == 0 || !(f[0] instanceof String))
		{
			f = client.getDBTableField(rows.get(0), DBTableID.SlayerTask.COL_NAME_LOWERCASE, 0);
		}
		if (f == null || f.length == 0 || !(f[0] instanceof String))
		{
			return null;
		}
		String name = (String) f[0];
		nameCache.put(taskId, name);
		return name;
	}

	public String areaName(int areaId)
	{
		String cached = areaCache.get(areaId);
		if (cached != null)
		{
			return cached;
		}
		List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerArea.ID, DBTableID.SlayerArea.COL_AREA_ID, 0, areaId);
		if (rows == null || rows.isEmpty())
		{
			return null;
		}
		Object[] f = client.getDBTableField(rows.get(0), DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER, 0);
		if (f == null || f.length == 0 || !(f[0] instanceof String))
		{
			f = client.getDBTableField(rows.get(0), DBTableID.SlayerArea.COL_AREA_TEXT, 0);
		}
		if (f == null || f.length == 0 || !(f[0] instanceof String))
		{
			return null;
		}
		String name = (String) f[0];
		areaCache.put(areaId, name);
		return name;
	}

	/** task id -> weight for one master, from the SlayerMasterTask table (empty when unavailable). */
	public Map<Integer, Integer> masterWeights(int masterId)
	{
		Map<Integer, Integer> cached = weightCache.get(masterId);
		if (cached != null)
		{
			return cached;
		}
		Map<Integer, Integer> out = new LinkedHashMap<>();
		try
		{
			List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerMasterTask.ID, DBTableID.SlayerMasterTask.COL_MASTER_ID, 0, masterId);
			if (rows != null)
			{
				for (int row : rows)
				{
					Object[] task = client.getDBTableField(row, DBTableID.SlayerMasterTask.COL_TASK, 0);
					Object[] weight = client.getDBTableField(row, DBTableID.SlayerMasterTask.COL_WEIGHT, 0);
					if (task != null && task.length > 0 && task[0] instanceof Integer && weight != null && weight.length > 0 && weight[0] instanceof Integer)
					{
						out.merge((Integer) task[0], (Integer) weight[0], Integer::sum);
					}
				}
			}
		}
		catch (RuntimeException e)
		{
			log.debug("master weights lookup failed", e);
		}
		if (!out.isEmpty())
		{
			weightCache.put(masterId, out);
		}
		return out;
	}

	/** Share of this master's rolls that land on the task, 0..1, or -1 when unknown. Ignores unlocks and blocks. */
	public double rollChance(int masterId, int taskId)
	{
		Map<Integer, Integer> w = masterWeights(masterId);
		if (w.isEmpty() || !w.containsKey(taskId))
		{
			return -1;
		}
		long total = 0;
		for (int v : w.values())
		{
			total += v;
		}
		return total <= 0 ? -1 : w.get(taskId) / (double) total;
	}

	/** Min and max amount this master assigns for the task, or null. */
	public int[] masterAmounts(int masterId, int taskId)
	{
		try
		{
			List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerMasterTask.ID, DBTableID.SlayerMasterTask.COL_MASTER_ID, 0, masterId);
			if (rows == null)
			{
				return null;
			}
			for (int row : rows)
			{
				Object[] task = client.getDBTableField(row, DBTableID.SlayerMasterTask.COL_TASK, 0);
				if (task != null && task.length > 0 && task[0] instanceof Integer && (Integer) task[0] == taskId)
				{
					Object[] min = client.getDBTableField(row, DBTableID.SlayerMasterTask.COL_MIN_AMOUNT, 0);
					Object[] max = client.getDBTableField(row, DBTableID.SlayerMasterTask.COL_MAX_AMOUNT, 0);
					if (min != null && max != null && min.length > 0 && max.length > 0 && min[0] instanceof Integer && max[0] instanceof Integer)
					{
						return new int[]{(Integer) min[0], (Integer) max[0]};
					}
				}
			}
		}
		catch (RuntimeException e)
		{
			log.debug("master amounts lookup failed", e);
		}
		return null;
	}

	public static String masterName(int masterId)
	{
		switch (masterId)
		{
			case 1: return "Turael";
			case 2: return "Mazchna";
			case 3: return "Vannaka";
			case 4: return "Chaeldar";
			case 5: return "Duradel";
			case 6: return "Nieve";
			case 7: return "Krystilia";
			case 8: return "Konar";
			case 10: return "Mortimer";
			default: return "your master";
		}
	}
}

